"use client";

import React, { useEffect, useRef } from 'react';
import styles from './ElectricBackground.module.css';

const ElectricBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = canvas.width;
    let height = canvas.height;
    let frameCount = 0;

    const resize = () => {
      const parent = canvas.parentElement;
      if (parent) {
        width = canvas.width = parent.clientWidth;
        height = canvas.height = parent.clientHeight;
      } else {
        width = canvas.width = window.innerWidth;
        height = canvas.height = window.innerHeight;
      }
    };

    window.addEventListener('resize', resize);
    resize();

    interface Point {
      x: number;
      y: number;
    }

    const drawLightning = (x1: number, y1: number, x2: number, y2: number, displace: number) => {
      if (displace < 2) {
        ctx.lineTo(x2, y2);
        return;
      }
      
      let midX = (x1 + x2) / 2;
      let midY = (y1 + y2) / 2;
      midX += (Math.random() - 0.5) * displace;
      midY += (Math.random() - 0.5) * displace;
      
      drawLightning(x1, y1, midX, midY, displace / 2);
      drawLightning(midX, midY, x2, y2, displace / 2);
    };

    const draw = () => {
      frameCount++;
      ctx.globalCompositeOperation = 'source-over';
      // Clear canvas
      ctx.clearRect(0, 0, width, height);

      // Random flickering logic
      // "Connected" vs "Disconnected" states could be simulated by periods of activity and inactivity
      const isActive = Math.sin(Date.now() / 1000) > 0; // Slow pulse of "power availability"
      
      // But user wants "glitchy", so random bursts are better.
      const burst = Math.random() > 0.92; // 8% chance per frame to spark
      
      if (burst) {
          // Draw flash background
          if (Math.random() > 0.8) {
              ctx.fillStyle = `rgba(255, 255, 255, ${Math.random() * 0.1})`;
              ctx.fillRect(0, 0, width, height);
          }

          // Draw Lightning
          const numBolts = Math.floor(Math.random() * 3) + 1;
          
          for (let i = 0; i < numBolts; i++) {
            ctx.beginPath();
            const startX = Math.random() * width;
            const startY = 0;
            const endX = Math.random() * width;
            const endY = height;
            
            ctx.moveTo(startX, startY);
            
            // Color variation: Cyan to White
            const colorVal = Math.floor(Math.random() * 55) + 200;
            ctx.strokeStyle = `rgb(${colorVal-100}, ${colorVal}, 255)`;
            ctx.lineWidth = Math.random() * 2 + 1;
            ctx.shadowBlur = 15;
            ctx.shadowColor = '#00ffff';
            
            drawLightning(startX, startY, endX, endY, 150);
            ctx.stroke();
            
            // Horizontal glitches (static lines)
            if (Math.random() > 0.5) {
                const y = Math.random() * height;
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(width, y);
                ctx.strokeStyle = `rgba(255, 255, 255, ${Math.random() * 0.5})`;
                ctx.lineWidth = Math.random() * 1;
                ctx.stroke();
            }
          }
      }

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className={styles.container}>
      <canvas ref={canvasRef} className={styles.canvas} />
    </div>
  );
};

export default ElectricBackground;
